UPDATE content SET overview_uk = v.overview_uk, has_uk_translation = true FROM (VALUES
  (5249, '«Назустріч ясності» створює інтимні портрети восьми колишніх членів Церкви саєнтології, висвітлюючи, як вона приваблює справжніх вірян і що робить в ім''я релігії.'),
  (3070, 'Напруга зростає в бригаді з очищення від азбесту, яка працює в покинутій психіатричній лікарні з жахливим минулим, що, здається, повертається.'),
  (5342, 'Цей відвертий, глибокий погляд на знаменитий виступ Бейонсе на фестивалі Коачелла 2018 року розкриває емоційний шлях від творчого задуму до культурного руху.'),
  (5220, 'Визнаймо: щурів не надто люблять на цій планеті. Але, можливо, ця маленька розповідь про історію взаємин людей і щурів змінить ставлення світу. Принаймні на це сподіваються Ремі, зірка «Рататуя», та його неохочий брат Еміль, проводячи нас крізь світову історію з перспективи щура. Чому ми всі не можемо просто порозумітися?'),
  (4810, 'Шовініст Дам''єн прокидається у світі, де жінки та чоловіки помінялися ролями в суспільстві, і всім керують жінки.'),
  (4162, 'Літня китаянка, яка страждає від синдрому порожнього гнізда, отримує ще один шанс на материнство, коли один із її вареників оживає, перетворившись на веселого маленького хлопчика.'),
  (5336, 'Вернер Герцоґ отримує ексклюзивний доступ для зйомок усередині печери Шове на півдні Франції, знімаючи найдавніші відомі наскельні зображення людства у їхньому приголомшливому природному середовищі.'),
  (4599, 'Після смерті матері сестри Ніколь та Енні неохоче повертаються до батьківського дому, щоб віддати останню шану. Ночуючи в будинку, сестри відчувають таємничу присутність: вночі їх лякають звуки, предмети рухаються самі по собі, на підлогу падає фото невідомої жінки поруч з їхньою матір''ю. Енні починає бачити серію інтенсивних і тривожних снів — видінь, які приводять її до розкриття чогось жахливого з минулого матері, що нарешті виходить на поверхню.'),
  (6985, 'Цей документальний серіал присвячений одній із найжахливіших тем в історії: Голокосту та сумнозвісному концентраційному табору Аушвіц-Біркенау.'),
  (3137, 'Американський письменник, який живе в Римі, стає свідком замаху на вбивство, пов''язаного з серією вбивств у місті, і проводить власне розслідування, попри те що він та його дівчина самі стають мішенню вбивці.'),
  (5093, 'Хав''єр — це те, що ми називаємо «чоловік для галочки». Не беручи жодної участі в домашніх справах і вихованні дітей, він точно знає, що потрібно робити, і постійно сипле фразами на кшталт: «Ти просто не вмієш організуватися» або «Не нервуй». Хав''єру доведеться зіткнутися з реальністю, коли його дружина вирішує поїхати у відпустку й залишає його наодинці з п''ятьма дітьми (від чотирьох до дванадцяти років). Хаотична ситуація вдома поступово еволюціонує до абсолютної катастрофи, але водночас дає батькові та дітям можливість вперше по-справжньому пізнати одне одного й насолодитися спілкуванням.'),
  (4940, 'Привид і французький маркіз блукають Зимовим палацом у Санкт-Петербурзі, стаючи свідками сцен із різних періодів його історії.'),
  (5253, 'Нью-Йорк, 1980 рік. Троє абсолютно незнайомих людей випадково дізнаються, що вони — ідентичні трійнята, розлучені при народженні. Радісна зустріч 19-річних юнаків катапультує їх до міжнародної слави, але також відкриває надзвичайну і тривожну таємницю, що виходить за межі їхніх власних життів і може назавжди змінити наше розуміння людської природи.'),
  (4977, 'Отець Моріс, священник, який живе в римській колегії для священників, одного дня отримує виклик «вигнати» диявола з одержимого. Диявол виявляється веселим чоловіком на ім''я Джудітта. Отець Моріс навіть не підозрює, що цей тип диявола перевернет його життя з ніг на голову.'),
  (5178, 'Альфа, Бета та Гамма відправляють Даґа на безглузді місії, щоб самим полювати на Птаха Райського водоспаду. Можливо, Даґ виявить, що його справжнє місце — зовсім не там, де він шукав.'),
  (7016, 'Маленькі тварини вирушають у великі пригоди по всій Америці в драматичному серіалі про природу, що досліджує їхні приховані світи та епічні історії виживання.')
) AS v(id, overview_uk) WHERE content.id = v.id;
